-- Booking lifecycle templates dispatched through Core's notifications.send_template capability.
insert into notifications_ext.templates(template_key,title_translations,body_translations,channels,variables,is_active,metadata) values
('booking.staff.assigned',
 '{"fa-IR":"رزرو جدید به شما تخصیص داده شد","en-US":"New booking assigned","ar-SA":"تم تعيين حجز جديد لك","tr-TR":"Yeni rezervasyon size atandı","es-ES":"Nueva reserva asignada","ku-KU":"حجزێکی نوێ بۆ تۆ دیاریکرا","de-DE":"Neue Buchung zugewiesen","fr-FR":"Nouvelle réservation attribuée"}'::jsonb,
 '{"fa-IR":"رزرو {bookingId} به شما تخصیص داده شد.","en-US":"Booking {bookingId} was assigned to you.","ar-SA":"تم تعيين الحجز {bookingId} لك.","tr-TR":"{bookingId} rezervasyonu size atandı.","es-ES":"Se te asignó la reserva {bookingId}.","ku-KU":"حجزی {bookingId} بۆ تۆ دیاریکرا.","de-DE":"Buchung {bookingId} wurde Ihnen zugewiesen.","fr-FR":"La réservation {bookingId} vous a été attribuée."}'::jsonb,
 array['in_app','push'],array['bookingId','providerId','date','time'],true,'{"journey":"bookings","audience":"bookings"}'::jsonb),
('booking.status.changed',
 '{"fa-IR":"وضعیت رزرو تغییر کرد","en-US":"Booking status changed","ar-SA":"تغيّرت حالة الحجز","tr-TR":"Rezervasyon durumu değişti","es-ES":"Cambió el estado de la reserva","ku-KU":"دۆخی حجز گۆڕا","de-DE":"Buchungsstatus geändert","fr-FR":"Statut de réservation modifié"}'::jsonb,
 '{"fa-IR":"وضعیت رزرو {bookingId} به {status} تغییر کرد.","en-US":"Booking {bookingId} changed to {status}.","ar-SA":"تغيّرت حالة الحجز {bookingId} إلى {status}.","tr-TR":"{bookingId} rezervasyonu {status} durumuna geçti.","es-ES":"La reserva {bookingId} cambió a {status}.","ku-KU":"دۆخی حجزی {bookingId} بۆ {status} گۆڕا.","de-DE":"Buchung {bookingId} wurde auf {status} geändert.","fr-FR":"La réservation {bookingId} est passée à {status}."}'::jsonb,
 array['in_app','push'],array['bookingId','providerId','status','previousStatus'],true,'{"journey":"bookings","audience":"bookings"}'::jsonb),
('booking.rescheduled',
 '{"fa-IR":"زمان رزرو تغییر کرد","en-US":"Booking rescheduled","ar-SA":"تمت إعادة جدولة الحجز","tr-TR":"Rezervasyon yeniden planlandı","es-ES":"Reserva reprogramada","ku-KU":"کاتی حجز گۆڕدرا","de-DE":"Buchung umgebucht","fr-FR":"Réservation replanifiée"}'::jsonb,
 '{"fa-IR":"رزرو {bookingId} به {date} ساعت {time} منتقل شد.","en-US":"Booking {bookingId} moved to {date} at {time}.","ar-SA":"تم نقل الحجز {bookingId} إلى {date} الساعة {time}.","tr-TR":"{bookingId} rezervasyonu {date} {time} saatine taşındı.","es-ES":"La reserva {bookingId} se movió al {date} a las {time}.","ku-KU":"حجزی {bookingId} بۆ {date} کاتژمێر {time} گوازرایەوە.","de-DE":"Buchung {bookingId} wurde auf {date} um {time} verschoben.","fr-FR":"La réservation {bookingId} a été déplacée au {date} à {time}."}'::jsonb,
 array['in_app','push','email'],array['bookingId','providerId','date','time'],true,'{"journey":"bookings","audience":"bookings"}'::jsonb),
('booking.cancelled',
 '{"fa-IR":"رزرو لغو شد","en-US":"Booking cancelled","ar-SA":"تم إلغاء الحجز","tr-TR":"Rezervasyon iptal edildi","es-ES":"Reserva cancelada","ku-KU":"حجز هەڵوەشایەوە","de-DE":"Buchung storniert","fr-FR":"Réservation annulée"}'::jsonb,
 '{"fa-IR":"رزرو {bookingId} لغو شد.","en-US":"Booking {bookingId} was cancelled.","ar-SA":"تم إلغاء الحجز {bookingId}.","tr-TR":"{bookingId} rezervasyonu iptal edildi.","es-ES":"La reserva {bookingId} fue cancelada.","ku-KU":"حجزی {bookingId} هەڵوەشایەوە.","de-DE":"Buchung {bookingId} wurde storniert.","fr-FR":"La réservation {bookingId} a été annulée."}'::jsonb,
 array['in_app','push','email'],array['bookingId','providerId'],true,'{"journey":"bookings","audience":"bookings"}'::jsonb),
('booking.change.requested',
 '{"fa-IR":"درخواست تغییر رزرو از پرسنل","en-US":"Staff booking-change request","ar-SA":"طلب موظف لتغيير الحجز","tr-TR":"Personel rezervasyon değişikliği talebi","es-ES":"Solicitud de cambio del personal","ku-KU":"داواکاری گۆڕینی حجز لەلایەن ستاف","de-DE":"Buchungsänderung durch Personal angefragt","fr-FR":"Demande de modification du personnel"}'::jsonb,
 '{"fa-IR":"برای رزرو {bookingId} درخواست {requestType} ثبت شده است و نیاز به بررسی شما دارد.","en-US":"A {requestType} request for booking {bookingId} is waiting for your review.","ar-SA":"طلب {requestType} للحجز {bookingId} بانتظار مراجعتك.","tr-TR":"{bookingId} rezervasyonu için {requestType} talebi incelemenizi bekliyor.","es-ES":"Una solicitud {requestType} para la reserva {bookingId} espera tu revisión.","ku-KU":"داواکاری {requestType} بۆ حجزی {bookingId} چاوەڕێی پشکنینی تۆیە.","de-DE":"Eine {requestType}-Anfrage für Buchung {bookingId} wartet auf Ihre Prüfung.","fr-FR":"Une demande {requestType} pour la réservation {bookingId} attend votre validation."}'::jsonb,
 array['in_app','push'],array['bookingId','providerId','requestType'],true,'{"journey":"bookings","audience":"bookings"}'::jsonb),
('booking.change.approved',
 '{"fa-IR":"درخواست تغییر رزرو تأیید شد","en-US":"Booking-change request approved","ar-SA":"تمت الموافقة على طلب تغيير الحجز","tr-TR":"Rezervasyon değişiklik talebi onaylandı","es-ES":"Solicitud de cambio aprobada","ku-KU":"داواکاری گۆڕینی حجز پەسەند کرا","de-DE":"Buchungsänderung genehmigt","fr-FR":"Demande de modification approuvée"}'::jsonb,
 '{"fa-IR":"درخواست {requestType} برای رزرو {bookingId} تأیید شد.","en-US":"Your {requestType} request for booking {bookingId} was approved.","ar-SA":"تمت الموافقة على طلب {requestType} للحجز {bookingId}.","tr-TR":"{bookingId} rezervasyonu için {requestType} talebiniz onaylandı.","es-ES":"Tu solicitud {requestType} para la reserva {bookingId} fue aprobada.","ku-KU":"داواکاری {requestType} بۆ حجزی {bookingId} پەسەند کرا.","de-DE":"Ihre {requestType}-Anfrage für Buchung {bookingId} wurde genehmigt.","fr-FR":"Votre demande {requestType} pour la réservation {bookingId} a été approuvée."}'::jsonb,
 array['in_app','push'],array['bookingId','providerId','requestType'],true,'{"journey":"bookings","audience":"bookings"}'::jsonb),
('booking.change.rejected',
 '{"fa-IR":"درخواست تغییر رزرو رد شد","en-US":"Booking-change request rejected","ar-SA":"تم رفض طلب تغيير الحجز","tr-TR":"Rezervasyon değişiklik talebi reddedildi","es-ES":"Solicitud de cambio rechazada","ku-KU":"داواکاری گۆڕینی حجز ڕەتکرایەوە","de-DE":"Buchungsänderung abgelehnt","fr-FR":"Demande de modification refusée"}'::jsonb,
 '{"fa-IR":"درخواست {requestType} برای رزرو {bookingId} تأیید نشد.","en-US":"Your {requestType} request for booking {bookingId} was not approved.","ar-SA":"لم تتم الموافقة على طلب {requestType} للحجز {bookingId}.","tr-TR":"{bookingId} rezervasyonu için {requestType} talebiniz onaylanmadı.","es-ES":"Tu solicitud {requestType} para la reserva {bookingId} no fue aprobada.","ku-KU":"داواکاری {requestType} بۆ حجزی {bookingId} پەسەند نەکرا.","de-DE":"Ihre {requestType}-Anfrage für Buchung {bookingId} wurde nicht genehmigt.","fr-FR":"Votre demande {requestType} pour la réservation {bookingId} n’a pas été approuvée."}'::jsonb,
 array['in_app','push'],array['bookingId','providerId','requestType'],true,'{"journey":"bookings","audience":"bookings"}'::jsonb)
on conflict (template_key) do update set
 title_translations=excluded.title_translations,body_translations=excluded.body_translations,channels=excluded.channels,
 variables=excluded.variables,is_active=excluded.is_active,metadata=excluded.metadata,updated_at=now();
